class Worker:
    def handle(self, price, tax, items, mapping, target):
        subtotal = price + tax
        running: int = subtotal
        annotated: int
        annotated = running
        if (chosen := mapping.get("key")):
            running = running + chosen
        for item in items:
            running = running + item
        for other in items:
            running = running + other
        with open("log") as handle:
            buffer = handle.read()
        target.slot = running
        target[price] = buffer
        mapping = {"key": buffer}
        return Result(running, buffer, target)

